SELECT "order_number", "line_no", "item", "quantity", "on_hand", "outage", "quantity" - "on_hand" AS "short"
FROM (SELECT "t4"."order_number", "t4"."customer", "t4"."channel", "t4"."fulfilling_warehouse", "t4"."value", "t4"."placed_date", "t4"."state", "t4"."line_no", "t4"."item", "t4"."quantity", "t4"."unit_price", "t4"."ext_sales_price", "t4"."warehouse", "t4"."sold_date", "t4"."customer0", "t4"."channel0", "t4"."as_of_date", "t4"."quantity_on_hand", "t5"."warehouse" AS "warehouse0", "t5"."from_date", "t5"."to_date", "t5"."reason", COALESCE("t4"."quantity_on_hand", 0) AS "on_hand", "t5"."warehouse" IS NOT NULL AS "outage"
        FROM (SELECT "t1"."order_number", "t1"."customer", "t1"."channel", "t1"."fulfilling_warehouse", "t1"."value", "t1"."placed_date", "t1"."state", "t1"."line_no", "t1"."item", "t1"."quantity", "t1"."unit_price", "t1"."ext_sales_price", "t1"."warehouse", "t1"."sold_date", "t1"."customer0", "t1"."channel0", "t3"."as_of_date", "t3"."quantity_on_hand"
                FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                    LEFT JOIN (SELECT "inventory"."as_of_date", "inventory"."item", "inventory"."warehouse", "inventory"."quantity_on_hand"
                        FROM "inventory"
                            INNER JOIN (SELECT "item", "warehouse", MAX("as_of_date") AS "_ttrp_latest_n8"
                                FROM "inventory"
                                GROUP BY "item", "warehouse") AS "t2" ON "inventory"."item" = "t2"."item" AND "inventory"."warehouse" = "t2"."warehouse" AND "inventory"."as_of_date" = "t2"."_ttrp_latest_n8") AS "t3" ON "t1"."item" = "t3"."item" AND "t1"."warehouse" = "t3"."warehouse") AS "t4"
            LEFT JOIN (SELECT *
                FROM "warehouse_outage"
                WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t5" ON "t4"."warehouse" = "t5"."warehouse") AS "t6"
WHERE "t6"."outage" OR "t6"."on_hand" < "t6"."quantity"
